import{_ as t,o as r,c as a,ae as o}from"./chunks/framework.6sbzjNFX.js";const i=""+new URL("new-installation.CG7r7eUl.png",import.meta.url).href,n=""+new URL("location-yes.D5NxbsCd.png",import.meta.url).href,s=""+new URL("location-no.fI9PJ7eu.png",import.meta.url).href,y=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),p={name:"getting-started.md"};function d(c,e,h,l,u,g){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Script Launcher is a tiny tool written by me <strong>(rayokay)</strong> to solve a very niche problem:</p><p>It&#39;s very annoying to type long folder names just to run a single batch or exe file.</p><p><em>(In actuality, it was just made because I was bored, but we can gloss over that.)</em></p><p>So, how do you use it?</p><h2 id="setup-wizard" tabindex="-1">Setup Wizard <a class="header-anchor" href="#setup-wizard" aria-label="Permalink to &quot;Setup Wizard&quot;">​</a></h2><p>When you first launch Script Launcher, you&#39;ll be greeted with a screen that looks like this:</p><p><img src="'+i+'" alt="New installation image"></p><p>This is the <strong>setup wizard</strong>.</p><p>The setup wizard sets up Script Launcher and your configuration so that it works properly.</p><p>First, it needs to know where your scripts are stored. The default path is <code>~/Scripts</code> where <code>~</code> represents the <strong>home directory.</strong></p><p>If you don&#39;t know what that means, don&#39;t worry about it. Simply go with the default path.</p><p>If the default path is correct and is where you want to store it, type <code>Y</code> and then hit <code>Enter</code>.</p><p>If you did everything correctly, a screen like this should pop up if you said yes:</p><p><img src="'+n+'" alt="Image of terminal when user selected Y"></p><p>However, if you want to change the path, type <code>N</code>, hit <code>Enter</code> and type your desired path before hitting <code>Enter</code> again:</p><p><img src="'+s+'" alt="Image of terminal when user selected N and entered desired path"></p><p><em>Note: The wizard will use the default path from earlier (<code>~/Scripts</code>) if you press <code>N</code> and do not enter anything.</em></p><p>If you did this, you&#39;re all set!</p>',19)])])}const f=t(p,[["render",d]]);export{y as __pageData,f as default};
